  function eur(n) { return Math.round(n).toLocaleString(loc()) + (G.lang === 'fr' ? ' €' : ' EUR'); }
  function eurK(n) { return n >= 10000 ? (Math.round(n / 100) / 10).toLocaleString(loc()) + (G.lang === 'fr' ? ' k€' : 'k EUR') : eur(n); }
  function pct(x) { return (Math.round(x * 10) / 10).toLocaleString(loc()) + (G.lang === 'fr' ? ' %' : '%'); }
  function pct0(x) { return Math.round(x).toLocaleString(loc()) + (G.lang === 'fr' ? ' %' : '%'); }
