    g += tx(ml + pw / 2, H - 6, S('axDef'), 'mu', 'middle') + tx(14, mt + ph / 2, S('axAvg'), 'mu', 'middle', ' transform="rotate(-90 14 ' + r1(mt + ph / 2) + ')"');
